p=[[8,8,6],[6,3,6],[6,8,8]]
T=[list(x) for x in zip(*p)]
H=lambda a:[r[::-1] for r in a]
V=lambda a:a[::-1]
blocks=[]
for bi in range(3):
 row=[]
 for bj in range(3):
  b=V(T) if bi%2 else T
  if bj%2: b=H(b)
  row.append(b)
 blocks.append(row)
out=[]
for br in blocks:
 for i in range(3): out.append(sum((b[i] for b in br),[]))
print(out)
